module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire in,
    output reg  out
);

    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t current_state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    always_comb begin
        next_state = current_state;
        case (current_state)
            A: begin
                if (in) next_state = B;
                else    next_state = A;
            end
            B: begin
                if (in) next_state = B;
                else    next_state = C;
            end
            C: begin
                if (in) next_state = D;
                else    next_state = A;
            end
            D: begin
                if (in) next_state = B;
                else    next_state = C;
            end
            default: next_state = A;
        endcase
    end

    always_comb begin
        case (current_state)
            A: out = 1'b0;
            B: out = 1'b0;
            C: out = 1'b0;
            D: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

endmodule

