module tb_TopModule;
    reg clk;
    reg reset;
    reg in;
    wire out;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        #12;
        reset = 0;

        // At state A (after reset)
        // Check output is 0
        if (out !== 0) begin
            $display("SELFTEST FAIL: Reset state output is not 0 (got %b)", out);
            $finish;
        end

        // Test sequence:
        // A -> in=1 -> B
        // B -> in=1 -> B
        // B -> in=0 -> C
        // C -> in=1 -> D (output should be 0 until D, wait, output is Moore, so when in state D output is 1)
        // Let's trace carefully:
        // Current: A. in=1 -> next B. clk posedge -> State B. out=0
        // Current: B. in=1 -> next B. clk posedge -> State B. out=0
        // Current: B. in=0 -> next C. clk posedge -> State C. out=0
        // Current: C. in=1 -> next D. clk posedge -> State D. out=1

        // 1. in=1 -> state B
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 0) begin $display("SELFTEST FAIL: state B out"); $finish; end

        // 2. in=1 -> state B
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 0) begin $display("SELFTEST FAIL: state B out 2"); $finish; end

        // 3. in=0 -> state C
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 0) begin $display("SELFTEST FAIL: state C out"); $finish; end

        // 4. in=1 -> state D -> out should be 1
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1) begin $display("SELFTEST FAIL: state D out expected 1, got %b", out); $finish; end

        // Test D -> in=0 -> C
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 0) begin $display("SELFTEST FAIL: state C out from D"); $finish; end

        // Test C -> in=0 -> A
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 0) begin $display("SELFTEST FAIL: state A out from C"); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
